<?php session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../db.php'; require_once __DIR__ . '/../includes/helpers.php'; require_admin_auth(); $id=trim((string)($_GET['id']??'')); $st=db()->prepare('SELECT * FROM chatbot_conversations WHERE id=:id');$st->execute(['id'=>$id]);$c=$st->fetch(); $msgs=[]; if($c){$m=db()->prepare('SELECT * FROM chatbot_messages WHERE conversation_id=:id ORDER BY id ASC');$m->execute(['id'=>$id]);$msgs=$m->fetchAll();} ?><!doctype html><html><body><h1>Conversation <?=e($id)?></h1><?php if(!$c):?><p>Not found.</p><?php else:?><p>Lead: <?=e($c['lead_name']??'')?> / <?=e($c['lead_email']??'')?> / <?=e($c['lead_phone']??'')?></p><?php foreach($msgs as $m):?><p><strong><?=e($m['role'])?>:</strong> <?=nl2br(e($m['content']))?></p><?php endforeach;?><?php endif;?></body></html>
